import { useAlert } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import {
    Button,
    ButtonStrip,
    IconChevronDown16,
    IconChevronRight16,
    IconCopy16,
    IconLaunch16,
    IconSync16,
    Modal,
    ModalActions,
    ModalContent,
    ModalTitle,
    Tooltip,
} from '@dhis2/ui'
import { useQuery } from '@tanstack/react-query'
import React, { useId, useState } from 'react'
import { Schema, useBoundResourceQueryFn } from '../../../lib'
import {
    PagedResponse,
    PartialLoadedDisplayableModel,
} from '../../../types/models'
import { LinkButton } from '../../LinkButton'
import css from './Bulk.module.css'
import {
    getBulkDeleteErrorDetails,
    getBulkDeleteErrorSummary,
} from './bulkDeleteErrorSummary'
import { BulkDeleteResult } from './useBulkDeleteMutation'

type FailedResult = Extract<BulkDeleteResult, { status: 'failed' }>

type FailedItem = {
    id: string
    displayName: string
    summary: string
    details: string[]
}

type BulkDeleteErrorsDialogProps = {
    schema: Schema
    results: BulkDeleteResult[]
    retrying: boolean
    onRetry: (ids: string[]) => void
    onClose: () => void
}

const formatErrorsForClipboard = (items: FailedItem[]) =>
    items
        .map((item) =>
            [
                `${item.displayName} (${item.id}): ${item.summary}`,
                ...item.details.map((detail) => `  - ${detail}`),
            ].join('\n')
        )
        .join('\n\n')

export const BulkDeleteErrorsDialog = ({
    schema,
    results,
    retrying,
    onRetry,
    onClose,
}: BulkDeleteErrorsDialogProps) => {
    const failed = results.filter(
        (result): result is FailedResult => result.status === 'failed'
    )

    const failedIds = failed.map(({ id }) => id)
    const queryFn = useBoundResourceQueryFn()
    const { data: displayNamesData } = useQuery({
        queryKey: [
            {
                resource: schema.plural,
                params: {
                    fields: ['id', 'displayName'],
                    filter: [`id:in:[${failedIds.join(',')}]`],
                    paging: false,
                },
            },
        ] as const,
        queryFn: queryFn<PagedResponse<PartialLoadedDisplayableModel, string>>,
        enabled: failedIds.length > 0,
    })
    const displayNames = new Map(
        displayNamesData?.[schema.plural]?.map((model) => [
            model.id,
            model.displayName,
        ])
    )

    const failedItems: FailedItem[] = failed.map(({ id, error }) => ({
        id,
        displayName: displayNames.get(id) ?? id,
        summary: getBulkDeleteErrorSummary(error),
        details: getBulkDeleteErrorDetails(error),
    }))

    const { show: showCopiedAlert } = useAlert(
        i18n.t('Errors copied to clipboard'),
        { success: true }
    )
    const handleCopy = async () => {
        await navigator.clipboard.writeText(
            formatErrorsForClipboard(failedItems)
        )
        showCopiedAlert()
    }

    return (
        <Modal
            large
            onClose={retrying ? undefined : onClose}
            dataTest="bulk-delete-errors-dialog"
        >
            <ModalTitle>
                {i18n.t(
                    '{{failedCount}} of {{total}} items could not be deleted',
                    { failedCount: failed.length, total: results.length }
                )}
            </ModalTitle>
            <ModalContent>
                <ul className={css.errorList}>
                    {failedItems.map((item) => (
                        <FailedItemRow key={item.id} item={item} />
                    ))}
                </ul>
            </ModalContent>
            <ModalActions>
                <div className={css.errorActions}>
                    <Button
                        secondary
                        icon={<IconCopy16 />}
                        onClick={handleCopy}
                        disabled={retrying}
                    >
                        {i18n.t('Copy as list')}
                    </Button>
                    <ButtonStrip end>
                        <Button
                            secondary
                            icon={<IconSync16 />}
                            loading={retrying}
                            onClick={() => onRetry(failedIds)}
                            dataTest="bulk-delete-errors-retry-button"
                        >
                            {i18n.t('Retry')}
                        </Button>
                        <Button primary onClick={onClose} disabled={retrying}>
                            {i18n.t('Close')}
                        </Button>
                    </ButtonStrip>
                </div>
            </ModalActions>
        </Modal>
    )
}

const FailedItemRow = ({ item }: { item: FailedItem }) => {
    const [showDetails, setShowDetails] = useState(false)
    const detailsId = useId()
    const ChevronIcon = showDetails ? IconChevronDown16 : IconChevronRight16

    return (
        <li>
            <div className={css.errorRowHeader}>
                <button
                    type="button"
                    className={css.errorRowToggle}
                    aria-expanded={showDetails}
                    aria-controls={detailsId}
                    onClick={() => setShowDetails((prev) => !prev)}
                >
                    <span className={css.errorRowChevron}>
                        <ChevronIcon />
                    </span>
                    <span className={css.errorRowText}>
                        <span className={css.errorRowDisplayName}>
                            {item.displayName}
                        </span>
                        <span className={css.errorRowSummary}>
                            {item.summary}
                        </span>
                    </span>
                </button>
                <Tooltip content={i18n.t('Open in a new tab')}>
                    <LinkButton
                        small
                        secondary
                        to={{ pathname: item.id }}
                        target="_blank"
                        rel="noreferrer"
                        className={css.errorRowLink}
                    >
                        {i18n.t('Open')}
                        <IconLaunch16 />
                    </LinkButton>
                </Tooltip>
            </div>
            {showDetails && (
                <pre id={detailsId} className={css.errorRowDetails}>
                    {item.details.join('\n')}
                </pre>
            )}
        </li>
    )
}
